        ]
      },
      {
        "id": "day2",
        "title": "Day 2: Akihabara Tech & Michelin Sushi",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Akihabara_Electric_Town_2015.jpg/1200px-Akihabara_Electric_Town_2015.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/laptop.svg",
        "activities": [
          "Morning exploration of Akihabara Radio Kaikan and Yodobashi Camera (Free).",
          "Michelin-starred sushi lunch at Sushi Iwa or similar ($150 per person).",
          "Evening at a themed cafe or retro arcade in Electric Town ($30)."
        ]
      },
      {
        "id": "day3",
        "title": "Day 3: Hakone Day Trip",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Lake_Ashi_and_Mount_Fuji_from_Hakone_Moto-Hakone.jpg/1200px-Lake_Ashi_and_Mount_Fuji_from_Hakone_Moto-Hakone.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/mountain.svg",
        "activities": [
          "Use Hakone Free Pass for the \"Hakone Loop\" via cable car and ropeway ($45).",
          "Sightseeing cruise on Lake Ashi with views of Mt. Fuji (Included in pass).",
          "Visit Hakone Open-Air Museum ($12)."
        ]
      },
      {
        "id": "day4",
        "title": "Day 4: Harajuku Foliage & Shibuya Crossing",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Meiji_Jingu_Forest.jpg/1200px-Meiji_Jingu_Forest.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "activities": [
          "Walk through the forested paths of Meiji Jingu Shrine (Free).",
          "Shopping and street food (crepes/rainbow toast) on Takeshita Street ($25).",
          "Sunset views from Shibuya Sky observatory ($18)."
        ]
      },
      {
        "id": "day5",
        "title": "Day 5: Shinkansen to Kyoto & Gion",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Gion_at_Night.jpg/1200px-Gion_at_Night.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg",
        "activities": [
          "Morning Shinkansen ride to Kyoto Station ($95).",
          "Check into a traditional Machiya-style hotel or ryokan.",
          "Evening walk through Gion to spot Geiko and enjoy a Kaiseki dinner ($100)."
        ]
      },
      {
        "id": "day6",
        "title": "Day 6: Kiyomizu-dera & Southern Higashiyama",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Kiyomizu-dera_in_Autumn.jpg/1200px-Kiyomizu-dera_in_Autumn.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
        "activities": [
          "Visit Kiyomizu-dera Temple for the iconic wooden stage and autumn leaves ($4).",
          "Walk through Sannenzaka and Ninenzaka preserved streets (Free).",
          "Tea ceremony experience at a local tea house ($35)."
        ]
      },
      {
        "id": "day7",
        "title": "Day 7: Arashiyama Bamboo & River Views",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Arashiyama_Bamboo_Grove_Kyoto.jpg/1200px-Arashiyama_Bamboo_Grove_Kyoto.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/water.svg",
        "activities": [
          "Morning walk through the Bamboo Grove and Tenryu-ji Temple ($5).",
          "Scenic Sagano Romantic Train ride through the autumn valley ($6).",
          "Afternoon at the Iwatayama Monkey Park ($5)."
        ]
      },
      {
        "id": "day8",
        "title": "Day 8: Fushimi Inari & Nishiki Market",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Nishiki_Market_Kyoto_02.jpg/1200px-Nishiki_Market_Kyoto_02.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cup-hot.svg",
        "activities": [
          "Hike through the thousands of Torii gates at Fushimi Inari (Free).",
          "Lunch at Nishiki Market: try takoyaki, wagyu skewers, and mochi ($40).",
          "Evening visit to Yasaka Shrine for the lantern displays (Free)."
        ]
      },
      {
        "id": "day9",
        "title": "Day 9: Golden Pavilion & Return to Tokyo",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Kinkaku-ji_in_winter.jpg/1200px-Kinkaku-ji_in_winter.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/train-front.svg",
        "activities": [
          "Morning visit to Kinkaku-ji (Golden Pavilion) ($4).",
          "Afternoon Shinkansen back to Tokyo ($95).",
          "Farewell dinner in Tokyo (e.g., Shibuya or Shinjuku) ($50)."
        ]
      }
    ]
